function openTab(tab){const titles={overview:['Resumo mensal da loja','Vendas, anúncios, custos e líquido previsto no mês.'],margins:['Custos de produção','Seu perfil de custos é aplicado automaticamente a camisetas e kits.'],hermes:['Central do Hermes','Acompanhe análises, operação e limites de uso.'],products:['Catálogo inteligente','Composições, tamanhos e custos identificados automaticamente. Revise somente as exceções.'],history:['Histórico e auditoria','Consulte as versões salvas e acompanhe as alterações.'],roadmap:['Evolução da operação','Os próximos passos para ampliar as análises e a automação.']};if(!Object.hasOwn(titles,tab))tab='overview';if(tab==='products'){if(state)loadObservations();syncOnProductsOpen();}document.querySelectorAll('.workspace > section').forEach(section=>section.hidden=section.id!==tab);document.querySelectorAll('[data-tab]').forEach(button=>{const selected=button.dataset.tab===tab;button.classList.toggle('active',selected);if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});el('pageTitle').textContent=titles[tab][0];el('pageSubtitle').textContent=titles[tab][1];document.documentElement.dataset.activePanel=tab;}

document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>openTab(button.dataset.tab));document.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>openTab(button.dataset.open));
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(pollTimer);clearTimeout(shopOrdersRefreshTimer);shopOrdersRefreshTimer=null;clearTimeout(storeAdsRefreshTimer);storeAdsRefreshTimer=null;}else if(state){pollLive();loadShopOrders();refreshStoreAds({automatic:true});scheduleStoreAdsRefresh();}});
setInterval(()=>{if(document.hidden)return;updateShopSnapshotAge();updateObservationCaptureState();for(const button of el('jobs').querySelectorAll('[data-job-id]')){const job=rows.find(row=>row.id===button.dataset.jobId);if(job)button.textContent=jobLabel(job);}const selected=rows.find(job=>job.id===selectedJobId);if(selected&&['queued','running'].includes(selected.status))selectedResult();},1000);
initialize();
